appearances.css:
.lab{padding:4px;border-radius:6px;display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:10px}
.lab>.row:nth-child(1),.lab>.row:nth-child(2){display:contents}
.lab>.row:nth-child(1) select{flex:2 1 120px;font-size:10px;padding:3px}
.lab>.row:nth-child(2) label.row{flex:1 1 auto;flex-wrap:nowrap;gap:4px}
.lab>.row:nth-child(2) select{font-size:10px;padding:3px;min-width:0;flex:1}
.lab>.row:nth-child(3){flex:1 1 100%;gap:4px 10px;flex-wrap:nowrap}
.lab>.row:nth-child(3) select{font-size:10px;padding:3px;flex:0 1 auto}
.lab>.row:nth-child(3) label{white-space:nowrap}
.screen{flex:1 1 100%;height:84px;margin:0;border-radius:4px}
.actions{flex:1 1 100%;margin:0;gap:3px;flex-wrap:nowrap}
.actions button{flex:1 1 auto;font-size:9px;padding:3px 4px;white-space:nowrap}
.parameters{flex:1 1 100%;display:flex;flex-wrap:wrap;gap:4px;margin:0}
.sec{display:flex;flex-wrap:nowrap;padding:3px 3px 4px;border:1px solid var(--line);border-radius:4px;min-width:0;background:var(--card-2)}
.sec[data-group=timbre]{flex:5 1 205px}
.sec[data-group=memory]{flex:3 1 170px}
.sec[data-group=space]{flex:2 1 80px}
.sec[data-group=life]{flex:4 1 160px}
.sec[data-group=voice]{flex:3 1 120px}
.sec[data-group=out]{flex:1 1 44px}
.control{flex:1 1 0;min-width:0;padding:0;border:0;background:none;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-content:start;gap:0}
.control .label{display:contents}
.control .label span:first-child{order:3;font-size:7.5px;letter-spacing:-.03em;text-align:center;line-height:1.1;max-width:100%;color:var(--muted)}
.control .value{order:2;font-size:8px;line-height:1.1;white-space:nowrap}
.control .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.keyboard{flex:1 1 100%;margin:0;gap:2px}
.key{padding:7px 0 3px;font-size:8px;border-bottom-width:3px}
.status{flex:1 1 100%;margin:0;font-size:9px;line-height:1.2}
